      question: "Cloud Kicks社(CK)は、特定の顧客に関する情報を取引先責任者に、靴やアクセサリーに関する情報をカスタム商品オブジェクトに保存します。CKの管理者は、取引先責任者が複数の商品に興味があることを表すために何を使用すべきでしょうか。",
      choices: ["ロール","ルックアップ検索条件項目","連結オブジェクト","数式項目"],
