      question: "Ursa Major Solar社は、経費報告書の提出、振り分け、承認を簡素化するために、ユーザーを支援するガイド付き経費報告書プロセスを作りたいと考えています。このソリューションを構築するために、管理者はどのツールを使用する必要がありますか。2つ選びなさい。",
