      choices: ["保証有効期限項目のデフォルト値として数式を使用する。","購入日から1年後を表示する数式項目を作成する。","有効期限項目が入力されることを確認する入力規則を追加する。","保証有効期限項目をモバイルページレイアウトに含める。"],
