      category: "自動化",
      source: "tysonblog 第111問",
      question: "Cloud Kicks社では、7日以上開いているケースの所有者を変更する必要があります。管理者はこの要件をどのように対応すればよいですか。",
      choices: ["自動レスポンスルール","入力規則","エスカレーションルール","割り当てルール"],
