      explanation: `参照関係は1対多のリレーションシップを形成しつつ、子レコードへのアクセスを独立して制御することが可能です。これにより、子オブジェクトへのアクセスを制限することができ、各オブジェクトのセキュリティ設定を独立して設定することが可能です。このため、子レコードのセキュリティを独自に管理するために最適な選択肢です。
        ※ 積み上げ集計項目は、主従関係の主オブジェクトに対して、従レコードのデータを集計するための項目です。これはリレーションシップの作成そのものではなく、主従間のデータを集計するためのものです。リレーションシップのセキュリティを管理するものではありません。
        ※ 主従関係は1対多のリレーションシップを形成しますが、従レコードは主レコードに完全に連動します。これにより、主オブジェクトに対するアクセスがある場合、従オブジェクトへのアクセスも可能となり、セキュリティが独立していません。これでは従レコードへのアクセスを制限する要件には合致しません。
        ※ クロスオブジェクト数式項目は、関連する2つのオブジェクト間で差し込み項目を参照するために使用されます。しかし、クロスオブジェクト数式項目は、リレーションシップのセキュリティやアクセス制御を直接的に管理するためのものではありません。そのため、子レコードへのアクセスを制限することには適していません。`
